SELECT gen_random_uuid()::text, 'formula', '$x = \frac{-b \pm j\sqrt{4ac - b^2}}{2a}$', 'Quadratic with Complex Roots', '$ax^2 + bx + c = 0,\ b^2 < 4ac:\quad x = \frac{-b \pm j\sqrt{4ac - b^2}}{2a}$', NULL, 'A negative discriminant gives a pair of conjugate complex roots.', '[{"symbol":"$a, b, c$","meaning":"real coefficients"}]'::jsonb, 'Their sum is $-\frac{b}{a}$ and their product $\frac{c}{a}$, as for real roots.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Complex Numbers' AND t."subject" = 'Mathematics' AND s."normKey" = 'complex equations' AND s."active"), NULL, true, 'PENDING', now(), now()
