SELECT gen_random_uuid()::text, 'formula', '$Z_L = j\omega L$', 'Impedance of R, L and C', '$Z_R = R,\qquad Z_L = j\omega L = jX_L,\qquad Z_C = \frac{1}{j\omega C} = -jX_C$', NULL, 'Resistors, inductors and capacitors as complex numbers.', '[{"symbol":"$\\omega$","meaning":"$2\\pi f$"},{"symbol":"$X_L, X_C$","meaning":"reactances $\\omega L$ and $\\frac{1}{\\omega C}$"}]'::jsonb, '$\frac1j = -j$ is why the capacitor''s reactance is negative.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Complex Numbers' AND t."subject" = 'Mathematics' AND s."normKey" = 'phasor applications' AND s."active"), 'Impedance', true, 'PENDING', now(), now()
