SELECT gen_random_uuid()::text, 'formula', '$\mathbf{S} = \mathbf{V}\mathbf{I}^*$', 'Complex Power in AC Circuits', '$\mathbf{S} = \mathbf{V}\mathbf{I}^* = P + jQ,\qquad |\mathbf{S}| = VI,\qquad \text{pf} = \cos\theta = \frac{P}{|\mathbf{S}|}$', NULL, 'Real and reactive power in one complex number.', '[{"symbol":"$\\mathbf{V}, \\mathbf{I}$","meaning":"rms voltage and current phasors"},{"symbol":"$P, Q$","meaning":"real and reactive power"}]'::jsonb, 'The current is conjugated: V I without the star gives the wrong angle.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Complex Numbers' AND t."subject" = 'Mathematics' AND s."normKey" = 'phasor applications' AND s."active"), 'Power', true, 'PENDING', now(), now()
